import numpy as np

def test_hypothesis(inp, out):
    """Test hypothesis: output position has 0 if:
    - input has 5: stays 5
    - input has 6: stays 0 if column has multiple 5s in that column"""
    H = inp.shape
    for r in range(H[0]):
        for c in range(H[1]):
            if inp[r][c] == 5:
                # Should stay 5
                if out[r][c] != 5:
                    return False, f"Failed at ({r},{c}): input=5, output={out[r][c]}"
            elif inp[r][c] == 6:
                # Count 5s in column c
                ones = sum(inp[row][c] == 5 for row in range(H[0]))
                if ones >= 2:
                    # Should be 0 (6 in output)
                    if out[r][c] != 6:
                        return False, f"Failed at ({r},{c}): input=6, col has {ones} 5s, output={out[r][c]}"
                else:
                    # Should be 3
                    if out[r][c] != 3:
                        return False, f"Failed at ({r},{c}): input=6, col has {ones} 5s, output={out[r][c]}"
    return True, "All pass"

